/*
 * calc: evaluate one 64-bit signed integer expression per line.
 *
 * The evaluator is an operator-precedence (shunting-yard) parser with
 * explicit stacks, so deeply nested input cannot overflow the C stack.
 * Any syntax error, division by zero or overflow makes the line "error".
 */
#include "commands.h"
#include "util.h"

#include <inttypes.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdlib.h>

#define OP_NEG 'n'

typedef struct {
    int64_t *vals;
    size_t nvals, vals_cap;
    char *ops;
    size_t nops, ops_cap;
} Stacks;

static void push_val(Stacks *st, int64_t v)
{
    if (st->nvals == st->vals_cap) {
        st->vals_cap = st->vals_cap ? st->vals_cap * 2 : 64;
        st->vals = xrealloc(st->vals, sizeof *st->vals * st->vals_cap);
    }
    st->vals[st->nvals++] = v;
}

static void push_op(Stacks *st, char op)
{
    if (st->nops == st->ops_cap) {
        st->ops_cap = st->ops_cap ? st->ops_cap * 2 : 64;
        st->ops = xrealloc(st->ops, st->ops_cap);
    }
    st->ops[st->nops++] = op;
}

static int precedence(char op)
{
    switch (op) {
    case OP_NEG:
        return 3;
    case '*':
    case '/':
    case '%':
        return 2;
    case '+':
    case '-':
        return 1;
    default: /* '(' */
        return 0;
    }
}

/* Compute a op b; returns false on overflow or division by zero. */
static bool binary(char op, int64_t a, int64_t b, int64_t *out)
{
    switch (op) {
    case '+':
        if ((b > 0 && a > INT64_MAX - b) || (b < 0 && a < INT64_MIN - b))
            return false;
        *out = a + b;
        return true;
    case '-':
        if ((b < 0 && a > INT64_MAX + b) || (b > 0 && a < INT64_MIN + b))
            return false;
        *out = a - b;
        return true;
    case '*':
        if (a > 0 ? (b > 0 ? a > INT64_MAX / b : b < INT64_MIN / a)
                  : (b > 0 ? a < INT64_MIN / b : (a != 0 && b < INT64_MAX / a)))
            return false;
        *out = a * b;
        return true;
    case '/':
        if (b == 0 || (a == INT64_MIN && b == -1))
            return false;
        *out = a / b;
        return true;
    case '%':
        if (b == 0)
            return false;
        *out = b == -1 ? 0 : a % b;
        return true;
    default:
        return false;
    }
}

/* Pop the top operator and apply it to the value stack. */
static bool reduce(Stacks *st)
{
    char op = st->ops[--st->nops];
    if (op == OP_NEG) {
        int64_t *v = &st->vals[st->nvals - 1];
        if (*v == INT64_MIN)
            return false;
        *v = -*v;
        return true;
    }
    int64_t b = st->vals[--st->nvals];
    int64_t *a = &st->vals[st->nvals - 1];
    return binary(op, *a, b, a);
}

static bool is_blank(char c)
{
    return c == ' ' || c == '\t';
}

static bool is_digit(char c)
{
    return c >= '0' && c <= '9';
}

static bool evaluate(Stacks *st, const char *s, size_t len, int64_t *result)
{
    st->nvals = st->nops = 0;
    bool want_operand = true;
    size_t i = 0;

    while (i < len) {
        char c = s[i];
        if (is_blank(c)) {
            i++;
            continue;
        }
        if (want_operand) {
            if (is_digit(c)) {
                int64_t v = 0;
                for (; i < len && is_digit(s[i]); i++) {
                    int d = s[i] - '0';
                    if (v > (INT64_MAX - d) / 10)
                        return false;
                    v = v * 10 + d;
                }
                push_val(st, v);
                want_operand = false;
                continue;
            }
            if (c == '-')
                push_op(st, OP_NEG);
            else if (c == '(')
                push_op(st, '(');
            else
                return false;
        } else {
            if (c == '+' || c == '-' || c == '*' || c == '/' || c == '%') {
                int p = precedence(c);
                while (st->nops > 0 && precedence(st->ops[st->nops - 1]) >= p)
                    if (!reduce(st))
                        return false;
                push_op(st, c);
                want_operand = true;
            } else if (c == ')') {
                while (st->nops > 0 && st->ops[st->nops - 1] != '(')
                    if (!reduce(st))
                        return false;
                if (st->nops == 0)
                    return false;
                st->nops--;
            } else {
                return false;
            }
        }
        i++;
    }

    if (want_operand)
        return false;
    while (st->nops > 0) {
        if (st->ops[st->nops - 1] == '(' || !reduce(st))
            return false;
    }
    *result = st->vals[0];
    return true;
}

static bool is_blank_line(const char *s, size_t len)
{
    for (size_t i = 0; i < len; i++)
        if (!is_blank(s[i]))
            return false;
    return true;
}

int cmd_calc(void)
{
    LineReader lr;
    line_reader_init(&lr, stdin);
    Stacks st = {0};

    const char *s;
    size_t len;
    while (line_reader_next(&lr, &s, &len)) {
        if (is_blank_line(s, len))
            continue;
        int64_t v;
        if (evaluate(&st, s, len, &v))
            printf("%" PRId64 "\n", v);
        else
            fputs("error\n", stdout);
    }

    free(st.vals);
    free(st.ops);
    line_reader_free(&lr);
    return 0;
}

#ifndef SUITE_COMMANDS_H
#define SUITE_COMMANDS_H

/* Each subcommand reads stdin, writes stdout, and returns an exit status. */
int cmd_wordfreq(void);
int cmd_lru(void);
int cmd_calc(void);

#endif

/*
 * lru: an LRU cache simulator.
 *
 * Entries live in a growable node pool and are threaded on a doubly linked
 * recency list (head = most recent). A linear-probing hash table of node
 * indices, with backward-shift deletion, gives O(1) expected lookups.
 */
#include "commands.h"
#include "util.h"

#include <stdbool.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

enum {
    MAX_TOKEN = 64,
    MAX_CAPACITY = 1000000,
    POOL_INITIAL = 1024,
};

#define NIL UINT32_MAX

typedef struct {
    uint64_t hash;
    uint32_t prev;
    uint32_t next;
    uint8_t key_len;
    uint8_t val_len;
    char key[MAX_TOKEN];
    char val[MAX_TOKEN];
} Node;

typedef struct {
    size_t capacity; /* maximum number of keys held */
    size_t size;

    Node *nodes;
    uint32_t pool_len; /* nodes ever handed out */
    uint32_t pool_cap;
    uint32_t free_list; /* chained through `next` */

    uint32_t head; /* most recently used */
    uint32_t tail; /* least recently used */

    uint32_t *slots; /* node indices, NIL when empty */
    size_t slot_mask;
} Cache;

typedef struct {
    const char *ptr;
    size_t len;
} Token;

static void cache_init(Cache *c, size_t capacity)
{
    c->capacity = capacity;
    c->size = 0;
    c->pool_cap = POOL_INITIAL;
    c->nodes = xmalloc(sizeof(Node) * c->pool_cap);
    c->pool_len = 0;
    c->free_list = NIL;
    c->head = c->tail = NIL;
    size_t nslots = 2 * (size_t)POOL_INITIAL;
    c->slots = xmalloc(sizeof(uint32_t) * nslots);
    memset(c->slots, 0xff, sizeof(uint32_t) * nslots);
    c->slot_mask = nslots - 1;
}

static void cache_free(Cache *c)
{
    free(c->nodes);
    free(c->slots);
}

/* ---- hash index ---- */

static size_t index_find(const Cache *c, Token key, uint64_t hash)
{
    size_t i = hash & c->slot_mask;
    for (;;) {
        uint32_t n = c->slots[i];
        if (n == NIL)
            return i;
        const Node *node = &c->nodes[n];
        if (node->hash == hash && node->key_len == key.len && memcmp(node->key, key.ptr, key.len) == 0)
            return i;
        i = (i + 1) & c->slot_mask;
    }
}

static void index_insert_node(uint32_t *slots, size_t mask, const Node *nodes, uint32_t n)
{
    size_t i = nodes[n].hash & mask;
    while (slots[i] != NIL)
        i = (i + 1) & mask;
    slots[i] = n;
}

static void index_rebuild(Cache *c, size_t nslots)
{
    free(c->slots);
    c->slots = xmalloc(sizeof(uint32_t) * nslots);
    memset(c->slots, 0xff, sizeof(uint32_t) * nslots);
    c->slot_mask = nslots - 1;
    for (uint32_t n = c->head; n != NIL; n = c->nodes[n].next)
        index_insert_node(c->slots, c->slot_mask, c->nodes, n);
}

/* Remove the entry in slot i, shifting later probe-chain members back. */
static void index_remove_at(Cache *c, size_t i)
{
    size_t mask = c->slot_mask;
    size_t j = i;
    for (;;) {
        j = (j + 1) & mask;
        uint32_t n = c->slots[j];
        if (n == NIL)
            break;
        size_t home = c->nodes[n].hash & mask;
        /* Move n into the hole unless its home lies cyclically in (i, j]. */
        bool stays = i <= j ? (i < home && home <= j) : (i < home || home <= j);
        if (!stays) {
            c->slots[i] = n;
            i = j;
        }
    }
    c->slots[i] = NIL;
}

/* ---- recency list ---- */

static void list_unlink(Cache *c, uint32_t n)
{
    Node *node = &c->nodes[n];
    if (node->prev != NIL)
        c->nodes[node->prev].next = node->next;
    else
        c->head = node->next;
    if (node->next != NIL)
        c->nodes[node->next].prev = node->prev;
    else
        c->tail = node->prev;
}

static void list_push_front(Cache *c, uint32_t n)
{
    Node *node = &c->nodes[n];
    node->prev = NIL;
    node->next = c->head;
    if (c->head != NIL)
        c->nodes[c->head].prev = n;
    else
        c->tail = n;
    c->head = n;
}

static void touch(Cache *c, uint32_t n)
{
    if (c->head != n) {
        list_unlink(c, n);
        list_push_front(c, n);
    }
}

/* ---- node pool ---- */

static uint32_t node_alloc(Cache *c)
{
    if (c->free_list != NIL) {
        uint32_t n = c->free_list;
        c->free_list = c->nodes[n].next;
        return n;
    }
    if (c->pool_len == c->pool_cap) {
        c->pool_cap *= 2;
        c->nodes = xrealloc(c->nodes, sizeof(Node) * c->pool_cap);
    }
    return c->pool_len++;
}

static void node_release(Cache *c, uint32_t n)
{
    c->nodes[n].next = c->free_list;
    c->free_list = n;
}

/* Unlink, unindex and release the entry whose index slot is `slot`. */
static void remove_entry(Cache *c, size_t slot)
{
    uint32_t n = c->slots[slot];
    index_remove_at(c, slot);
    list_unlink(c, n);
    node_release(c, n);
    c->size--;
}

/* ---- commands ---- */

static void cache_set(Cache *c, Token key, Token val)
{
    uint64_t hash = hash_bytes(key.ptr, key.len);
    size_t slot = index_find(c, key, hash);
    uint32_t n = c->slots[slot];
    if (n != NIL) {
        Node *node = &c->nodes[n];
        memcpy(node->val, val.ptr, val.len);
        node->val_len = (uint8_t)val.len;
        touch(c, n);
        return;
    }

    if (c->size == c->capacity) {
        /* Evicting first is equivalent to inserting then evicting: the
         * victim is never the new key. */
        const Node *victim = &c->nodes[c->tail];
        Token vkey = {victim->key, victim->key_len};
        remove_entry(c, index_find(c, vkey, victim->hash));
        slot = index_find(c, key, hash);
    }

    n = node_alloc(c);
    Node *node = &c->nodes[n];
    node->hash = hash;
    node->key_len = (uint8_t)key.len;
    node->val_len = (uint8_t)val.len;
    memcpy(node->key, key.ptr, key.len);
    memcpy(node->val, val.ptr, val.len);
    list_push_front(c, n);
    c->slots[slot] = n;
    c->size++;

    if (c->size * 2 > c->slot_mask + 1)
        index_rebuild(c, (c->slot_mask + 1) * 2);
}

static void cache_get(Cache *c, Token key)
{
    size_t slot = index_find(c, key, hash_bytes(key.ptr, key.len));
    uint32_t n = c->slots[slot];
    if (n == NIL) {
        fputs("NULL\n", stdout);
        return;
    }
    touch(c, n);
    const Node *node = &c->nodes[n];
    fwrite(node->val, 1, node->val_len, stdout);
    putchar('\n');
}

static void cache_del(Cache *c, Token key)
{
    size_t slot = index_find(c, key, hash_bytes(key.ptr, key.len));
    if (c->slots[slot] == NIL) {
        fputs("0\n", stdout);
        return;
    }
    remove_entry(c, slot);
    fputs("1\n", stdout);
}

/* ---- parsing ---- */

static bool valid_token(Token t)
{
    return t.len >= 1 && t.len <= MAX_TOKEN;
}

/* Split `s` at its first space into head and tail (tail empty if none). */
static void split(Token s, Token *head, Token *tail)
{
    const char *sp = memchr(s.ptr, ' ', s.len);
    if (!sp) {
        *head = s;
        *tail = (Token){s.ptr + s.len, 0};
        return;
    }
    size_t n = (size_t)(sp - s.ptr);
    *head = (Token){s.ptr, n};
    *tail = (Token){sp + 1, s.len - n - 1};
}

static bool token_is(Token t, const char *word)
{
    size_t n = strlen(word);
    return t.len == n && memcmp(t.ptr, word, n) == 0;
}

static bool parse_capacity(Token t, size_t *out)
{
    size_t v = 0;
    size_t i = 0;
    while (i < t.len && (t.ptr[i] == ' ' || t.ptr[i] == '\t'))
        i++;
    size_t digits = 0;
    for (; i < t.len && t.ptr[i] >= '0' && t.ptr[i] <= '9'; i++, digits++) {
        v = v * 10 + (size_t)(t.ptr[i] - '0');
        if (v > MAX_CAPACITY)
            return false;
    }
    while (i < t.len && (t.ptr[i] == ' ' || t.ptr[i] == '\t'))
        i++;
    if (digits == 0 || i != t.len || v < 1)
        return false;
    *out = v;
    return true;
}

/* Malformed command lines are ignored. */
static void run_command(Cache *c, Token line)
{
    Token cmd, rest, key, val, extra;
    split(line, &cmd, &rest);
    if (token_is(cmd, "SET")) {
        split(rest, &key, &val);
        if (valid_token(key) && valid_token(val) && !memchr(val.ptr, ' ', val.len))
            cache_set(c, key, val);
    } else if (token_is(cmd, "GET")) {
        split(rest, &key, &extra);
        if (valid_token(key) && extra.len == 0)
            cache_get(c, key);
    } else if (token_is(cmd, "DEL")) {
        split(rest, &key, &extra);
        if (valid_token(key) && extra.len == 0)
            cache_del(c, key);
    } else if (token_is(cmd, "SIZE") && rest.len == 0 && line.len == 4) {
        printf("%zu\n", c->size);
    }
}

static Token line_token(const char *s, size_t len)
{
    if (len > 0 && s[len - 1] == '\r')
        len--;
    return (Token){s, len};
}

int cmd_lru(void)
{
    LineReader lr;
    line_reader_init(&lr, stdin);

    const char *s;
    size_t len;
    size_t capacity;
    if (!line_reader_next(&lr, &s, &len) || !parse_capacity(line_token(s, len), &capacity)) {
        line_reader_free(&lr);
        return 0;
    }

    Cache cache;
    cache_init(&cache, capacity);
    while (line_reader_next(&lr, &s, &len))
        run_command(&cache, line_token(s, len));

    cache_free(&cache);
    line_reader_free(&lr);
    return 0;
}

#include "commands.h"
#include "util.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static const struct {
    const char *name;
    int (*run)(void);
} commands[] = {
    {"wordfreq", cmd_wordfreq},
    {"lru", cmd_lru},
    {"calc", cmd_calc},
};

static void usage(void)
{
    fputs("usage: app <wordfreq|lru|calc>  (reads stdin, writes stdout)\n", stderr);
}

int main(int argc, char **argv)
{
    if (argc != 2) {
        usage();
        return 2;
    }
    for (size_t i = 0; i < sizeof commands / sizeof commands[0]; i++) {
        if (strcmp(argv[1], commands[i].name) == 0) {
            setup_stdout();
            int status = commands[i].run();
            if (fflush(stdout) != 0 || ferror(stdout))
                die("write error on standard output");
            return status;
        }
    }
    usage();
    return 2;
}

#include "util.h"

#include <stdlib.h>
#include <string.h>

_Noreturn void die(const char *msg)
{
    fprintf(stderr, "app: %s\n", msg);
    exit(EXIT_FAILURE);
}

void *xmalloc(size_t size)
{
    void *p = malloc(size ? size : 1);
    if (!p)
        die("out of memory");
    return p;
}

void *xrealloc(void *ptr, size_t size)
{
    void *p = realloc(ptr, size ? size : 1);
    if (!p)
        die("out of memory");
    return p;
}

void *xcalloc(size_t count, size_t size)
{
    void *p = calloc(count ? count : 1, size ? size : 1);
    if (!p)
        die("out of memory");
    return p;
}

void setup_stdout(void)
{
    static char outbuf[1 << 16];
    setvbuf(stdout, outbuf, _IOFBF, sizeof outbuf);
}

size_t next_pow2(size_t n)
{
    size_t p = 1;
    while (p < n)
        p <<= 1;
    return p;
}

enum { LINE_READER_INITIAL = 1 << 16 };

void line_reader_init(LineReader *lr, FILE *fp)
{
    lr->fp = fp;
    lr->cap = LINE_READER_INITIAL;
    lr->buf = xmalloc(lr->cap);
    lr->start = 0;
    lr->end = 0;
    lr->eof = 0;
}

void line_reader_free(LineReader *lr)
{
    free(lr->buf);
    lr->buf = NULL;
}

/* Make room after the unconsumed data and read more of the stream. */
static void line_reader_fill(LineReader *lr)
{
    size_t pending = lr->end - lr->start;
    if (lr->start > 0) {
        memmove(lr->buf, lr->buf + lr->start, pending);
        lr->start = 0;
        lr->end = pending;
    }
    if (lr->end == lr->cap) {
        lr->cap *= 2;
        lr->buf = xrealloc(lr->buf, lr->cap);
    }
    size_t got = fread(lr->buf + lr->end, 1, lr->cap - lr->end, lr->fp);
    if (got == 0) {
        if (ferror(lr->fp))
            die("read error on standard input");
        lr->eof = 1;
    }
    lr->end += got;
}

int line_reader_next(LineReader *lr, const char **line, size_t *len)
{
    size_t scanned = 0;
    for (;;) {
        char *base = lr->buf + lr->start;
        size_t avail = lr->end - lr->start;
        char *nl = memchr(base + scanned, '\n', avail - scanned);
        if (nl) {
            *line = base;
            *len = (size_t)(nl - base);
            lr->start += *len + 1;
            return 1;
        }
        if (lr->eof) {
            if (avail == 0)
                return 0;
            *line = base;
            *len = avail;
            lr->start = lr->end;
            return 1;
        }
        scanned = avail;
        line_reader_fill(lr);
    }
}

#ifndef SUITE_UTIL_H
#define SUITE_UTIL_H

#include <stddef.h>
#include <stdint.h>
#include <stdio.h>

/* Allocation wrappers: abort the program with a message on exhaustion. */
void *xmalloc(size_t size);
void *xrealloc(void *ptr, size_t size);
void *xcalloc(size_t count, size_t size);
_Noreturn void die(const char *msg);

/* Give stdout a large buffer; call before any output. */
void setup_stdout(void);

/* Smallest power of two >= n (n >= 1). */
size_t next_pow2(size_t n);

/* FNV-1a with a final avalanche so low bits are usable for table indexing. */
static inline uint64_t hash_finish(uint64_t h)
{
    h ^= h >> 33;
    h *= 0xff51afd7ed558ccdULL;
    h ^= h >> 33;
    h *= 0xc4ceb9fe1a85ec53ULL;
    h ^= h >> 33;
    return h;
}

#define FNV_OFFSET 0xcbf29ce484222325ULL
#define FNV_PRIME 0x100000001b3ULL

static inline uint64_t hash_bytes(const char *s, size_t len)
{
    uint64_t h = FNV_OFFSET;
    for (size_t i = 0; i < len; i++) {
        h ^= (unsigned char)s[i];
        h *= FNV_PRIME;
    }
    return hash_finish(h);
}

/*
 * Line reader over a FILE*. Yields lines without their terminating '\n';
 * a final line lacking '\n' is still returned. The returned pointer is
 * valid until the next call.
 */
typedef struct {
    FILE *fp;
    char *buf;
    size_t cap;
    size_t start;
    size_t end;
    int eof;
} LineReader;

void line_reader_init(LineReader *lr, FILE *fp);
int line_reader_next(LineReader *lr, const char **line, size_t *len);
void line_reader_free(LineReader *lr);

#endif

/*
 * wordfreq: count case-folded runs of ASCII letters and print the ten most
 * frequent, by count descending then word ascending.
 *
 * Input is streamed in chunks; a word cut off at the end of a chunk is moved
 * to the front of the buffer and completed by the next read. Distinct words
 * are copied into an arena and indexed by an open-addressing hash table.
 */
#include "commands.h"
#include "util.h"

#include <stdbool.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

enum {
    CHUNK_SIZE = 1 << 20,
    ARENA_BLOCK = 1 << 20,
    TABLE_INITIAL = 1 << 12,
    TOP_N = 10,
};

typedef struct {
    const char *word; /* NULL marks an empty slot */
    size_t len;
    uint64_t hash;
    uint64_t count;
} Entry;

typedef struct {
    Entry *slots;
    size_t cap; /* power of two */
    size_t used;
} WordTable;

typedef struct ArenaBlock {
    struct ArenaBlock *next;
    size_t used;
    size_t cap;
    char data[];
} ArenaBlock;

typedef struct {
    ArenaBlock *head;
} Arena;

static const char *arena_copy(Arena *a, const char *s, size_t len)
{
    ArenaBlock *b = a->head;
    if (!b || b->cap - b->used < len) {
        size_t cap = len > ARENA_BLOCK ? len : ARENA_BLOCK;
        b = xmalloc(sizeof *b + cap);
        b->next = a->head;
        b->used = 0;
        b->cap = cap;
        a->head = b;
    }
    char *dst = b->data + b->used;
    memcpy(dst, s, len);
    b->used += len;
    return dst;
}

static void arena_free(Arena *a)
{
    while (a->head) {
        ArenaBlock *next = a->head->next;
        free(a->head);
        a->head = next;
    }
}

static void table_grow(WordTable *t)
{
    size_t new_cap = t->cap * 2;
    Entry *slots = xcalloc(new_cap, sizeof *slots);
    size_t mask = new_cap - 1;
    for (size_t i = 0; i < t->cap; i++) {
        const Entry *e = &t->slots[i];
        if (!e->word)
            continue;
        size_t j = e->hash & mask;
        while (slots[j].word)
            j = (j + 1) & mask;
        slots[j] = *e;
    }
    free(t->slots);
    t->slots = slots;
    t->cap = new_cap;
}

/* Count one occurrence of an already lowercased word. */
static void table_add(WordTable *t, Arena *arena, const char *word, size_t len, uint64_t hash)
{
    size_t mask = t->cap - 1;
    size_t i = hash & mask;
    for (;;) {
        Entry *e = &t->slots[i];
        if (!e->word)
            break;
        if (e->hash == hash && e->len == len && memcmp(e->word, word, len) == 0) {
            e->count++;
            return;
        }
        i = (i + 1) & mask;
    }
    t->slots[i] = (Entry){arena_copy(arena, word, len), len, hash, 1};
    if (++t->used * 4 > t->cap * 3)
        table_grow(t);
}

static bool is_letter(unsigned char c)
{
    return (unsigned char)((c | 0x20) - 'a') < 26;
}

/*
 * Fold and count every complete word in buf[0, len). When `final` is false,
 * a word touching the end may continue in the next chunk; its start offset
 * is returned so the caller can carry it over. Otherwise returns len.
 */
static size_t count_words(WordTable *t, Arena *arena, char *buf, size_t len, bool final)
{
    size_t i = 0;
    while (i < len) {
        if (!is_letter((unsigned char)buf[i])) {
            i++;
            continue;
        }
        size_t start = i;
        uint64_t h = FNV_OFFSET;
        while (i < len && is_letter((unsigned char)buf[i])) {
            char c = (char)(buf[i] | 0x20);
            buf[i] = c;
            h = (h ^ (unsigned char)c) * FNV_PRIME;
            i++;
        }
        if (i == len && !final)
            return start;
        table_add(t, arena, buf + start, i - start, hash_finish(h));
    }
    return len;
}

/* Order: count descending, then word ascending by bytes. */
static bool ranks_before(const Entry *a, const Entry *b)
{
    if (a->count != b->count)
        return a->count > b->count;
    size_t n = a->len < b->len ? a->len : b->len;
    int c = memcmp(a->word, b->word, n);
    if (c != 0)
        return c < 0;
    return a->len < b->len;
}

static void print_top(const WordTable *t)
{
    const Entry *top[TOP_N];
    size_t n = 0;
    for (size_t i = 0; i < t->cap; i++) {
        const Entry *e = &t->slots[i];
        if (!e->word)
            continue;
        if (n == TOP_N && !ranks_before(e, top[n - 1]))
            continue;
        size_t pos = n < TOP_N ? n++ : TOP_N - 1;
        while (pos > 0 && ranks_before(e, top[pos - 1])) {
            top[pos] = top[pos - 1];
            pos--;
        }
        top[pos] = e;
    }
    for (size_t i = 0; i < n; i++)
        printf("%llu %.*s\n", (unsigned long long)top[i]->count, (int)top[i]->len, top[i]->word);
}

int cmd_wordfreq(void)
{
    WordTable table = {xcalloc(TABLE_INITIAL, sizeof(Entry)), TABLE_INITIAL, 0};
    Arena arena = {NULL};
    size_t cap = CHUNK_SIZE;
    char *buf = xmalloc(cap);
    size_t carry = 0;

    for (;;) {
        /* Keep each read at least as large as the carried-over word so a
         * very long word is not rescanned a quadratic number of times. */
        if (cap - carry < CHUNK_SIZE / 2 || cap - carry < carry) {
            while (cap - carry < CHUNK_SIZE / 2 || cap - carry < carry)
                cap *= 2;
            buf = xrealloc(buf, cap);
        }
        size_t got = fread(buf + carry, 1, cap - carry, stdin);
        if (got == 0 && ferror(stdin))
            die("read error on standard input");
        size_t len = carry + got;
        bool final = got == 0;
        size_t rest = count_words(&table, &arena, buf, len, final);
        if (final)
            break;
        carry = len - rest;
        memmove(buf, buf + rest, carry);
    }

    print_top(&table);
    free(buf);
    free(table.slots);
    arena_free(&arena);
    return 0;
}
